// Define the basic type structure for our pub/sub bus
// Add your TypeScript types and interfaces here

// Define the EventHandler type here
type EventHandler<T> = (payload: T) => void;

// Define the EventMap interface here
interface EventMap {
  [event: string]: any;
}

// Create the PubSubBus class skeleton here
class PubSubBus<T extends EventMap> {
  // Add the private handlers property here
  private handlers = new Map<string, Function[]>();

  // Add the subscribe method here
  subscribe<K extends keyof T>(event: K, handler: EventHandler<T[K]>): void {
    const eventHandlers = this.handlers.get(event as string) || [];
    eventHandlers.push(handler);
    this.handlers.set(event as string, eventHandlers);
  }

  // Add the unsubscribe method here
  unsubscribe<K extends keyof T>(event: K, handler: EventHandler<T[K]>): void {
    const eventHandlers = this.handlers.get(event as string);
    if (eventHandlers) {
      const index = eventHandlers.indexOf(handler);
      if (index > -1) {
        eventHandlers.splice(index, 1);
      }
    }
  }

  // Implement the publish method here
  publish<K extends keyof T>(event: K, payload: T[K]): void {
    const eventHandlers = this.handlers.get(event as string) || [];
    eventHandlers.forEach(handler => handler(payload));
  }
}

